entries[986] = { ["name"] = "Foliant des Frostblitzes II", ["text"] = "Klassen: Magier\nBenötigt Stufe 8\nBenutzen: Lehrt 'Frostblitz' (Rang 2).\nSchleudert einen Frostblitz auf den Feind, der 33 bis 38 Frostschaden verursacht und 6 Sek. lang das Bewegungstempo um 40% reduziert.\nVerkaufspreis:" }
entries[989] = { ["name"] = "Foliant der Frostnova", ["text"] = "Klassen: Magier\nBenötigt Stufe 10\nBenutzen: Lehrt 'Frostnova' (Rang 1).\nFügt in der Nähe des Zaubernden befindlichen Feinden 21 bis 24 Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen.\nVerkaufspreis:" }
entries[992] = { ["name"] = "Foliant des Feuerballs III", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Feuerball' (Rang 3).\nSchleudert eine glühende Kugel hinaus, die 57 bis 77 Feuerschaden sowie 6 Sek. lang insgesamt 6 zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:" }
entries[994] = { ["name"] = "Foliant der Eisrüstung", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Eisrüstung' (Rang 1).\nErhöht die Rüstung um 290 und den Frostwiderstand um 6. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\nVerkaufspreis:" }
