entries[1029] = { ["name"] = "Schrifttafel des Schlangentotems", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Totem der Schlange' (Rang 1).\nBeschwört 30 Sek. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 9 bis 11 Punkt(e) Feuerschaden anrichtet.\nVerkaufspreis:" }
