entries[1032] = { ["name"] = "Schrifttafel des aufstachelnden Totems", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 1).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 50 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
