entries[1086] = { ["name"] = "Kodex des inneren Feuers", ["text"] = "Klassen: Priester\nBenötigt Stufe 12\nBenutzen: Lehrt 'Inneres Feuer' (Rang 1).\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 315 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind.\nVerkaufspreis:" }
