entries[1136] = { ["name"] = "Buchband: Göttliche Gunst II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 18\nBenutzen: Lehrt 'Göttlicher Schutz' (Rang 2).\nSchützt 8 Sek. lang vor allen körperlichen Angriffen und Zaubern, allerdings kann man dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Einmal geschützt, kann man 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden.\nVerkaufspreis:" }
