entries[1224] = { ["name"] = "Zauberfoliant des Dämonenspürsinns", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 24\nBenutzen: Lehrt 'Dämonenerspürung'.\nZeigt den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an, bis abgebrochen wird. Es kann immer nur jeweils eine Art des Fährtenlesens benutzt werden.\nVerkaufspreis:" }
entries[1228] = { ["name"] = "Zauberfoliant des Siedebluts", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 6\nBenutzen: Lehrt 'Siedeblut' (Rang 1).\nVerkaufspreis:" }
entries[1229] = { ["name"] = "Zauberfoliant der Seelensteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 18\nBenutzen: Lehrt 'Seelenstein herstellen'.\nLässt einen schwachen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nSchwacher Seelenstein\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Speichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden. (30 Min Abklingzeit)\nBenötigt Seelensplitter" }
entries[1231] = { ["name"] = "Zauberfoliant des Schattenblitzes II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 6\nBenutzen: Lehrt 'Schattenblitz' (Rang 2).\nSendet einen schattigen Blitz zum Gegner, der 26 bis 32 Schattenschaden verursacht.\nVerkaufspreis:" }
entries[1232] = { ["name"] = "Zauberfoliant der Dämonenhaut II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 10\nBenutzen: Lehrt 'Dämonenhaut' (Rang 2).\nSchützt den Zaubernden, indem es 30 Min. lang die Rüstung um 120 erhöht und alle 5 Sek. 5 Gesundheit wiederherstellt.\nVerkaufspreis:" }
entries[1238] = { ["name"] = "Zauberfoliant der Furcht", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 8\nBenutzen: Lehrt 'Furcht' (Rang 1).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 10 Sek. lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden.\nVerkaufspreis:" }
entries[1239] = { ["name"] = "Zauberfoliant des Manaentzugs", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Mana entziehen' (Rang 1).\nÜberträgt alle 1 Sek. 42 Mana vom Ziel auf den Zaubernden. Hält 5 Sek. lang an.\nVerkaufspreis:" }
entries[1243] = { ["name"] = "Zauberfoliant des Schattenblitzes III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Schattenblitz' (Rang 3).\nSendet einen schattigen Blitz zum Gegner, der 52 bis 61 Schattenschaden verursacht.\nVerkaufspreis:" }
entries[1244] = { ["name"] = "Zauberfoliant der Dämonenrüstung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Dämonenrüstung' (Rang 1).\nSchützt den Zaubernden und erhöht die Rüstung um 210, den Schattenwiderstand um 3 und stellt alle 5 Sek. 7 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an.\nVerkaufspreis:" }
entries[1245] = { ["name"] = "Zauberfoliant des Feuerbrandes II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 10\nBenutzen: Lehrt 'Feuerbrand' (Rang 2).\nVerbrennt den Feind und fügt 24 Feuerschaden sowie 15 Sek. lang insgesamt 40 zusätzlichen Feuerschaden zu.\nVerkaufspreis:" }
entries[1246] = { ["name"] = "Zauberfoliant des Dämonenatems", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 16\nBenutzen: Lehrt 'Dämonenatem'.\nErmöglicht dem Ziel 10 Min. lang das Atmen unter Wasser.\nVerkaufspreis:" }
